/** user-defined types **/

/**
 * Wire-format error returned to the frontend across the IPC boundary. Every
 * `#[tauri::command]` returns `Result<T, AppError>` so the renderer always
 * receives the same `{ code, message }` shape — this lets UI code switch on
 * `code` for retry/rollback decisions instead of parsing the message string.
 */
export type AppError = { code: string; message: string }
export type Asset = { id: AssetId; kind: AssetKind; relative_path: string; original_filename: string; mime_type: string | null; size_bytes: number | null; sha256: string | null; metadata_json: string | null; created_at: number; updated_at: number; deleted_at: number | null }
export type AssetId = number
export type AssetKind = "stl" | "gcode" | "image" | "cad" | "scad" | "obj" | "step" | "cadquery" | "threemf" | "markdown" | "other"
/**
 * An asset attached to an object plus role + sort info plus type-specific metadata.
 */
export type AttachedAsset = { asset: Asset; role: ObjectAssetRole; sort_order: number; gcode_metadata: GcodeMetadata | null; mesh_metadata: MeshMetadata | null }
export type CreateObjectInput = { name: string; folder_id: FolderId | null; notes: string | null; source_url: string | null; author: string | null; license: string | null; stl_paths: string[]; cover_image_path: string | null }
export type Folder = { id: FolderId; parent_id: FolderId | null; name: string; created_at: number; updated_at: number; deleted_at: number | null }
export type FolderId = number
export type FolderImportReport = { object: Object; stl_count: number; gcode_count: number; image_count: number; other_count: number; skipped_count: number }
export type GcodeMetadata = { asset_id: AssetId; slicer_name: string | null; slicer_version: string | null; profile_name: string | null; layer_height_mm: number | null; nozzle_temp_c: number | null; bed_temp_c: number | null; estimated_time_seconds: number | null; filament_length_mm: number | null; filament_weight_g: number | null; filament_type: string | null; parsed_at: number | null; export_to_usb: boolean }
export type ImportSource = "thingiverse"
/**
 * Computed geometry for a mesh-bearing asset (STL now; OBJ/3MF/SCAD-render later).
 * Distances are in the file's own units — millimeters for STL/OBJ, whatever
 * `source_units` declares for 3MF.
 */
export type MeshMetadata = { asset_id: AssetId; source_format: string | null; source_units: string | null; triangle_count: number | null; vertex_count: number | null; bbox_x_mm: number | null; bbox_y_mm: number | null; bbox_z_mm: number | null; volume_mm3: number | null; surface_area_mm2: number | null; is_watertight: boolean | null; parsed_at: number | null }
export type MountedDrive = { mount_path: string; label: string | null; fs_kind: string | null }
/**
 * Outcome of [`new_project`], surfaced to the frontend so it can tailor the
 * toast (a clean build vs. a degraded fallback). Serializes to a snake_case
 * string on the wire.
 */
export type NewProjectOutcome = 
/**
 * A `<name>.3mf` already existed in the object dir; opened it as-is.
 */
"opened_existing" | 
/**
 * Built a fresh `<name>.3mf` headlessly and opened it.
 */
"built_and_opened" | 
/**
 * Headless build failed/timed out; loaded the raw STLs into a new GUI
 * project instead (the user must Save Project themselves).
 */
"fell_back_to_stls"
export type Object = { id: ObjectId; folder_id: FolderId | null; name: string; notes: string | null; source_url: string | null; author: string | null; license: string | null; cover_asset_id: AssetId | null; created_at: number; updated_at: number }
/**
 * Role of an asset within an object.
 */
export type ObjectAssetRole = "stl_part" | "gcode" | "scad" | "document" | "attachment"
export type ObjectFull = { object: Object; assets: AttachedAsset[]; tags: Tag[]; 
/**
 * The object's "main" `.3mf` project: the user's explicit pick if set,
 * otherwise the most recently updated `.3mf`. `None` if the object has no
 * `.3mf` assets.
 */
main_project_asset_id: AssetId | null }
export type ObjectId = number
export type ObjectSummary = { id: ObjectId; folder_id: FolderId | null; name: string; cover_asset_id: AssetId | null; stl_count: number; gcode_count: number; updated_at: number }
/**
 * The configured default printer/filament preset file paths (if any).
 */
export type OrcaDefaults = { machine_path: string | null; filament_path: string | null }
/**
 * A selectable OrcaSlicer preset discovered on disk. `path` is the JSON file we
 * hand to the CLI; `name`/`vendor` are for display.
 */
export type OrcaPreset = { name: string; vendor: string; path: string }
/**
 * Presets available to choose as defaults, grouped by kind.
 */
export type OrcaPresets = { machines: OrcaPreset[]; filaments: OrcaPreset[] }
/**
 * Output of the parser. Extras (anything we couldn't model) are stashed in `assets.metadata_json`.
 */
export type ParsedGcode = { slicer_name: string | null; slicer_version: string | null; profile_name: string | null; layer_height_mm: number | null; nozzle_temp_c: number | null; bed_temp_c: number | null; estimated_time_seconds: number | null; filament_length_mm: number | null; filament_weight_g: number | null; filament_type: string | null; raw_extras: { [key in string]: string } }
export type SearchHit = { entity_kind: string; entity_id: number; name: string; snippet: string }
export type SyncReport = { copied: number; updated: number; deleted: number; skipped: boolean; reason: string | null; errors: string[]; started_at: number; finished_at: number }
export type Tag = { id: TagId; name: string; color: string | null; created_at: number }
export type TagId = number
export type UpdateObjectPatch = { name?: string | null; notes?: string | null; source_url?: string | null; author?: string | null; license?: string | null }
export type UrlImportReport = { object: Object; source: ImportSource; 
/**
 * Number of model files (.stl / .3mf / .obj) downloaded into the object.
 */
model_files_imported: number; 
/**
 * Number of files that were listed by the source but skipped (unsupported extension).
 */
files_skipped: number; 
/**
 * True if a cover image was set from the source.
 */
cover_imported: boolean; 
/**
 * Set when the source has files we could fetch but the user has not configured the
 * required credentials (e.g. a Thingiverse API token).
 */
auth_required: boolean; 
/**
 * Human-readable warning to surface in the UI, if any.
 */
warning: string | null }
export type UsbTarget = { uuid: string; label: string; registered_at: number }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
